comms.text:
@1 אִלֵין מִנְיָנֵי מַשְׁכְּנָא מַשְׁכְּנָא דְסַהֲדוּתָא דִי אִתְמְנֵי עַל מֵימְרָא דְמשֶׁה פָּלְחַן לֵיוָאֵי בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@2 וּבְצַלְאֵל בַּר אוּרִי בַר חוּר לְשִׁבְטָא דִיהוּדָה עֲבַד יָת כָּל דִי פַקֵיד יְיָ יָת משֶׁה:
@3 וְעִמֵהּ אָהֳלִיאָב בַּר אֲחִיסָמָךְ לְשִׁבְטָא דְדָן נַגָר וָאֳמָן וְצַיָר בְּתִכְלָא וּבְאַרְגְוָנָא וּבִצְבַע זְהוֹרִי וּבְבוּצָא:
@4 כָּל דַהֲבָא דְאִתְעֲבֵד לְעִבִידָא בְּכֹל עִבִידַת קוּדְשָׁא וַהֲוָה דְהַב אֲרָמוּתָא עֶסְרִין וּתְשַׁע כִּכְּרִין וּשְׁבַע מְאָה וּתְלָתִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא:
@5 וּכְסַף מִנְיָנֵי כְנִשְׁתָּא מְאָה כִכְּרִין וְאֶלֶף וּשְׁבַע מְאָה וְשִׁבְעִין וְחַמְשָׁא סִלְעִין בְּסִלְעֵי קוּדְשָׁא:
@6 תִּקְלָּא לְגֻלְגַלְתָּא פַלְגוּת סִלְעָא בְּסִלְעֵי קוּדְשָׁא לְכֹל דְעָבַר עַל מִנְיָנַיָא מִבַּר עֶסְרִין שְׁנִין וּלְעֵלָא לְשִׁית מְאָה וּתְלָתָא אַלְפִין וַחֲמֵשׁ מְאָה וְחַמְשִׁין:
@7 וַהֲוָה מְאָה כִכְּרִין דִכְסַף לְאַתָּכָא יָת סַמְכֵי קוּדְשָׁא וְיָת סַמְכֵי דְפָרֻכְתָּא מְאָה סַמְכִין לִמְאָה כִכְּרִין כִּכְּרָא לְסַמְכָא:
@8 וְיָת אַלְפָא וּשְׁבַע מְאָה וְשִׁבְעִין וְחַמְשָׁא עֲבַד וָוִין לְעַמוּדַיָא וְחִפָּא רֵישֵׁיהוֹן וְכַבֵּשׁ יָתְהוֹן:
@9 וּנְחָשָׁא דַאֲרָמוּתָא שִׁבְעִין כִּכְּרִין וּתְרֵין אַלְפִין וְאַרְבַּע מְאָה סִלְעִין:
@10 וַעֲבַד בַּהּ יָת סַמְכֵי תְּרַע מַשְׁכַּן זִמְנָא וְיָת מַדְבְּחָא דִנְחָשָׁא וְיָת סְרָדָא דִנְחָשָׁא דִי לֵהּ וְיָת כָּל מָנֵי מַדְבְּחָא:
@11 וְיָת סַמְכֵי דְדַרְתָּא סְחוֹר סְחוֹר וְיָת סַמְכֵי תְּרַע דַרְתָּא וְיָת כָּל סִכֵּי מַשְׁכְּנָא וְיָת כָּל סִכֵּי דַרְתָּא סְחוֹר סְחוֹר:
@12 וּמִן תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עֲבָדוּ לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְּקוּדְשָׁא וַעֲבָדוּ יָת לְבוּשֵׁי קוּדְשָׁא דִי לְאַהֲרֹן כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@13 וַעֲבַד יַת אֵפוֹדָא דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@14 וְרַדִידוּ יָת טַסֵי דַהֲבָא וְקַצִיצוּ חוּטִין לְמֶעְבַּד בְּגוֹ תִּכְלָא וּבְגוֹ אַרְגְוָנָא וּבְגוֹ צְבַע זְהוֹרִי וּבְגוֹ בוּצָא עוֹבַד אֳמָן:
@15 כַּתְפָּן עֲבָדוּ לֵהּ מְלַפְּפָן עַל תְּרֵין סִטְרוֹהִי יִתְלָפֵף:
@16 וְהֶמְיַן תִּקוּנֵהּ דִי עֲלוֹהִי מִנֵהּ הוּא כְּעוֹבָדוֹהִי דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@17 וַעֲבָדוּ יָת אַבְנֵי בוּרְלָא מְשַׁקְעָן מְרַמְצָן דִדְהָב גְלִיפָן כְּתַב מְפָרַשׁ עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל:
@18 וְשַׁוִי יָתְהוֹן עַל כִּתְפָא דְאֵפוֹדָא אַבְנֵי דוּכְרָנָא לִבְנֵי יִשְׂרָאֵל כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@19 וַעֲבַד יָת חוּשְׁנָא עוֹבַד אֳמָן כְּעוֹבְדֵי אֵפוֹדָא דַהֲבָּא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@20 מְרַבַּע הֲוָה עֵיף עֲבָדוּ יָת חוּשְׁנָא זֶרְתָּא אֻרְכֵּהּ וְזֶרְתָּא פְתָיֵהּ עֵיף:
@21 וְאַשְׁלִימוּ בֵהּ אַרְבְּעָא סִדְרֵי אֶבֶן טָבָא סִדְרָא קַדְמָאָה סַמְקָן יַרְקָן וּבַרְקָן סִדְרָא חָד:
@22 וְסִדְרָא תִּנְיָנָא אִזְמָרַגְדִין שַׁבְזִיז וְסַבְהֲלוֹם:
@23 וְסִדְרָא תְּלִיתָאָה קַנְכֵּרֵי טַרְקְיָא וְעֵין עֶגְלָא:
@24 וְסִדְרָא רְבִיעָאָה כְּרוּם יַמָּא וּבוּרְלָא וּפַנְטֵּרֵי מְשַׁקְעָן מְרַמְצָן דִדְהַב בְּאַשְׁלָמוּתְהוֹן:
@25 וְאַבְנַיָא עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל אִנוּן תַּרְתֵּי עֶסְרֵי עַל שְׁמָהַתְהוֹן כְּתַב מְפָרַשׁ כִּגְלוֹף דְעִזְקָא גְבַר עַל שְׁמֵהּ לִתְרֵין עֲסַר שִׁבְטִין:
@26 וַעֲבָדוּ עַל חוּשְׁנָא תִּכִּין מְתַחְמָן עוֹבַד גְדִילוּ דְהַב דְכֵי:
@27 וַעֲבָדוּ תַּרְתֵּין מְרַמְצָן דִדְהַב וְתַרְתֵּין עִזְקָן דִדְהָב וִיהָבוּ יָת תַּרְתֵּין עִזְקָתָא עַל תְּרֵין סִטְרֵי חוּשְׁנָא:
@28 וִיהָבוּ תַּרְתֵּין גְדִילָתָא דִדְהַב עַל תַּרְתֵּין עִזְקָתָא עַל סִטְרֵי חוּשְׁנָא:
@29 וְיָת תַּרְתֵּין גְדִילָן דְעַל תַּרְתֵּין סִטְרוֹהִי יְהָבוּ עַל תַּרְתֵּין מְרַמְצָתָא וִיהָבֻנוּן עַל כַּתְפֵּי אֵפוֹדָא לָקֳבֵל אַפּוֹהִי:
@30 וַעֲבָדוּ תַּרְתֵּין עִזְקַן דִדְהַב וְשַׁוִיאוּ עַל תְּרֵין סִטְרֵי חוּשְׁנָא עַל סִפְתֵהּ דִי לְעִבְרָא דְאֵפוֹדָא מִלְגָיו:
@31 וַעֲבָדוּ תַּרְתֵּין עִזְקַן דִדְהַב וִיהָבֻנוּן עַל תַּרְתֵּין כִּתְפֵי אֵפוֹדָא מִלְרַע מִלָקֳבֵל אַפּוֹהִי לָקֳבֵל בֵּית לוֹפֵי מֵעִלָוֵי לְהֶמְיַן אֵפוֹדָא:
@32 וְיַחֲדוּן יָת חוּשְׁנָא מֵעִזְקְתֵהּ לְעִזְקָתָא דְאֵפוֹדָא בְּחוּטָּא דִתְכֶלְתָּא לְמֶהֱוֵי עַל הֶמְיַן אֵפוֹדָא וְלָא יִתְפָּרֵק חוּשְׁנָא מֵעִלָוֵי אֵפוֹדָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@33 וַעֲבַד יָת מְעִילָא דְאֵפוֹדָא עוֹבַד מָחֵי גְמִיר תִּכְלָא:
@34 וּפוּם מְעִילָא כָּפִיל לְגַוֵהּ כְּפוּם שִׁרְיָן תּוֹרָא מַקַף לְפוּמֵהּ סְחוֹר סְחוֹר לָא יִתְבְּזָע:
@35 וַעֲבָדוּ עַל שִׁפּוֹלֵי מְעִילָא רִמוֹנֵי תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי שְׁזִיר:
@36 וַעֲבָדוּ זַגַיָא דְהַב דְכֵי וִיהָבוּ יָת זַגַיָא בְּגוֹ רִמוֹנַיָא עַל שִׁפּוֹלֵי מְעִילָא סְחוֹר סְחוֹר בְּגוֹ רִמוֹנַיָא:
@37 זַגָא וְרִמוֹנָא זַגָא וְרִמוֹנָא עַל שִׁפּוֹלֵי מְעִילָא סְחוֹר סְחוֹר לְשַׁמָשָׁא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@38 וַעֲבָדוּ יָת כִּתּוּנִין דְבוּצָא עוֹבַד מָחֵי לְאַהֲרֹן וִלִבְנוֹהִי:
@39 וְיָת מִצְנֶפְתָּא דְבוּצָא וְיָת שְׁבַח כּוֹבָעַיָא דְבוּצָא וְיָת מִכְנְסֵי בוּצָא דְבוּץ שְׁזִיר:
@40 וְיָת הֶמְיָנָא דְבוּץ שְּׁזִיר וְתִכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עוֹבַד צַיָר כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@41 וַעֲבָדוּ יָת צִיצָא כְלִילָא דְקוּדְשָׁא דְהַב דְכֵי וּכְתָבוּ עֲלוֹהִי גְלִיפָן כְּתַב מְפָרַשׁ קֹדֶשׁ לַיְיָ:
@42 וִיהָבוּ עֲלוֹהִי חוּטָא תְכֶלְתָּא לְמִתַּן עַל מִצְנֶפְתָּא מִלְעֵלָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@43 וּשְׁלִים כָּל פָּלְחַן מַשְׁכְּנָא מַשְׁכַּן זִמְנָא וַעֲבָדוּ בְּנֵי יִשְׂרָאֵל כְּכֹל דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ:
@44 וְאַיְתִיוּ יָת מַשְׁכְּנָא לְמשֶׁה יָת מַשְׁכְּנָא וְיָת כָּל מָנוֹהִי פוּרְפוֹהִי דַפּוֹהִי עַבְּרוֹהִי וְעַמוּדוֹהִי וְסַמְכוֹהִי:
@45 וְיָת חוֹפָאָה מַשְׁכֵי דְדִכְרֵי מְסַמְקֵי וְיָת חוֹפָאָה מַשְׁכֵי דְסַסְגוֹנָא וְיָת פָּרֻכְתָּא דִפְרָסָא:
@46 יָת אֲרוֹנָא דְסַהֲדוּתָא וְיָת אֲרִיחוֹהִי וְיָת כַּפֻּרְתָּא:
@47 יָת פָּתוֹרָא יָת כָּל מָנוֹהִי וְיָת לְחֵם אַפַּיָא:
@48 יָת מְנַרְתָּא דָכִיתָא יָת בּוֹצִינָהָא בּוֹצִנֵי סִדְרָא וְיָת כָּל מָנָהָא וְיָת מִשְׁחָא דְאַנְהָרוּתָא:
@49 וְיָת מַדְבְּחָא דְדַהֲבָא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת קְטֹרֶת בּוּסְמַיָא וְיָת פְּרָסָא דִתְרַע מַשְׁכְּנָא:
@50 יָת מַדְבְּחָא דִנְחָשָׁא וְיָת סְרָדָא דִנְחָשָׁא דִילֵהּ יָת אֲרִיחוֹהִי וְיָת כָּל מָנוֹהִי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ:
@51 יָת סְרָדֵי דְדַרְתָּא יָת עַמוּדָהָא וְיָת סַמְכָהָא וְיָת פְּרָסָא לִתְרַע דַרְתָּא יָת אֲטוּנוֹהִי וְסִכָּהָא וְיָת כָּל מָנֵי פָּלְחַן מַשְׁכְּנָא לְמַשְׁכַּן זִמְנָא:
@52 יָת לְבוּשֵׁי שִׁמוּשָׁא לְשַׁמָשָׁא בְקוּדְשָׁא יָת לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן כַּהֲנָא וְיָת לְבוּשֵׁי בְנוֹהִי לְשַׁמָשָׁא:
@53 כְּכֹל דִי פַקִיד יְיָ יָת משֶׁה כֵּן עֲבָדוּ בְּנֵי יִשְׂרָאֵל יָת כָּל פָּלְחָנָא:
@54 וַחֲזָא משֶׁה יָת כָּל עִבִדְתָּא וְהָא עֲבָדוּ יָתַהּ כְּמָא דִי פַקִיד יְיָ כֵּן עֲבָדוּ וּבָרִיךְ יָתְהוֹן משֶׁה:
@55 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@56 בְּיוֹמָא יַרְחָא קַדְמָאָה בְּחַד לְיַרְחָא תְּקִים יָת מַשְׁכְּנָא מַשְּׁכַּן זִמְנָא:
@57 וּתְשַׁוֵי תַמָן יַת אֲרוֹנָא דְסַהֲדוּתָא וְתַטֵּל עַל אֲרוֹנָא יָת פָּרֻכְתָּא:
@58 וְתָעֵל יָת פָּתוֹרָא וְתַסְדַר יָת סִדְרֵהּ וְתָעֵל יָת מְנַרְתָּא וְתַדְלֵק יָת בּוֹצִינָהָא:
@59 וְתִתֵּן יָת מַדְבְּחָא דְדַהֲבָא לִקְטֹּרֶת בּוּסְמַיָא קֳדָם אֲרוֹנָא דְסַהֲדוּתָא וּתְשַׁוֵי יָת פְּרָסָא דְתַרְעָא לְמַשְׁכְּנָא:
@60 וְתִתֵּן יָת מַדְבְּחָא דַעֲלָתָא קֳדָם תְּרַע מַשְׁכְּנָא מַשְׁכַּן זִמְנָא:
@61 וְתִתֵּן יָת כִּיוֹרָא בֵּין מַשְׁכַּן זִמְנָא וּבֵין מַדְבְּחָא וְתִתֵּן תַּמָן מַיָא:
@62 וּתְשַׁוֵי יָת דַרְתָּא סְחוֹר סְחוֹר וְתִתֵּן יָת פְּרָסָא דִתְרַע דַרְתָּא:
@63 וְתִסַב יָת מִשְׁהָא דִרְבוּתָא וּתְרַבֵּי יָת מַשְׁכְּנָא וְיָת כָּל דִי בֵהּ וּתְקַדֵשׁ יָתֵהּ וְיָת כָּל מָנוֹהִי וִיהֵי קוּדְשָׁא:
@64 וּתְרַבֵי יָת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל מָנוֹהִי וּתְקַדֵשׁ יָת מַדְבְּחָא וִיהֵי מַדְבְּחָא קֹדֶשׁ קוּדְשִׁין:
@65 וּתְרַבֵּי יָת כִּיוֹרָא וְיָת בְּסִיסֵהּ וּתְקַדֵשׁ יָתֵהּ:
@66 וּתְקָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי לִתְרַע מַשְׁכַּן זִמְנָא וְתַסְחֵי יָתְהוֹן בְּמַיָא:
@67 וְתַלְבֵּשׁ יָת אַהֲרֹן יָת לְבוּשֵׁי קוּדְשָׁא וּתְרַבֵּי יָתֵהּ וּתְקַדֵשׁ יָתֵהּ וִישַׁמֵשׁ קֳדָמָי:
@68 וְיָת בְּנוֹהִי תְּקָרֵב וְתַלְבֵּשּׁ יָתְהוֹן כִּתּוּנִין:
@69 וּתְרַבִּי יָתְהוֹן כְּמָא דִי רַבִּיתָא יָת אֲבוּהוֹן וִישַׁמְשׁוּן קֳדָמָי וּתְהֵי לְמֶהֱוֵי לְּהוֹן רְבוּתְהוֹן לְכַהֲנוּת עֲלָם לְדָרֵיהוֹן:
@70 וַעֲבַד משֶׁה כְּכֹל דִי פַקִיד יְיָ יָתֵהּ כֵּן עֲבָד:
@71 וַהֲוָה בְּיַרְחָא קַדְמָאָה בְּשַׁתָּא תִנְיֵתָא בְּחַד לְיַרְחָא אִתָּקַם מַשְׁכְּנָא:
@72 וַאֲקֵם משֶׁה יָת מַשְׁכְּנָא וִיהַב יָת סַמְכוֹהִי וְשַׁוִי יָת דַפּוֹהִי וִיהַב יָת עַבְרוֹהִי וַאֲקֵם יָת עַמוּדוֹהִי:
@73 וּפְרַס יָת פְרָסָא עַל מַשְׁכְּנָא וְשַׁוִי יָת חוֹפָאָה דְמַשְׁכְּנָא עֲלוֹהִי מִלְעֵלָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@74 וּנְסִיב וִיהַב יָת סַהֲדוּתָא לַאֲרוֹנָא וְשַׁוִי יָת אֲרִיחַיָא עַל אֲרוֹנָא וִיהַב יָת כַּפֻּרְתָּא עַל אֲרוֹנָא מִלְעֵלָא:
@75 וְאָעֵלּ יָת אֲרוֹנָא לְמַשְׁכְּנָא וְשַׁוִי יָת פָּרֻכְתָּא דִפְרָסָא וְאַטֵל עַל אֲרוֹנָא דְסַהֲדוּתָא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@76 וִיהַב יָת פָּתוֹרָא בְּמַשְׁכַּן זִמְנָא עַל צִדָא דְמַשְׁכְּנָא צִפוּנָא מִבָּרָא לְפָרֻכְתָּא:
@77 וְסַדַר עֲלוֹהִי סִדוּר דִלְחֵם קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@78 וְשַׁוִי יָת מְנַרְתָּא בְּמַשְׁכַּן זִמְנָא לָקֳבֵל פָּתוֹרָא עַל צִדָא דְמַשְׁכְּנָא לְדָרוֹמָא:
@79 וְאַדְלֵק בּוֹצִינָהָא קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@80 וְשַׁוִי יָת מַדְבְּחָא דְדַהֲבָא בְּמַשְׁכַּן זִמְנָא קֳדָם פָּרֻכְתָּא:
@81 וְאַקְטַּר עֲלוֹהִי קְטֹרֶת בּוּסְמִין כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@82 וְשַׁוִי יָת פְּרָסָא דְתַרְעָא לְמַשְׁכְּנָא:
@83 וְיָת מַדְבְּחָא דַעֲלָתָא שַׁוִי בִּתְרַע מַשְׁכְּנָא מַשְׁכַּן זִמְנָא וְאַסֵק עֲלוֹהִי יָת עֲלָתָא וְיָת מִנְחָתָּא כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@84 וְשַׁוִי יָת כִּיוֹרָא בֵּין מַשְׁכַּן זִמְנָא וּבֵין מַדְבְּחָא וִיהַב תַּמָן מַיָא לְקִדוּשׁ:
@85 וּמְקַדְשִׁין מִנֵהּ משֶׁה וְאַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן וְיָת רַגְלֵיהוֹן:
@86 בְּמֵעַלְהוֹן לְמַשְׁכַּן זִמְנָא וּבְמִקְרָבְהוֹן לְמַדְבְּחָא יְקַדְשׁוּן כְּמָא דִי פַקִיד יְיָ יָת משֶׁה:
@87 וַאֲקֵם יָת דַרְתָּא סְחוֹר סְחוֹר לְמַשְׁכְּנָא וּלְמַדְבְּחָא וִיהַב יָת פְּרָסָא דִתְרַע דַרְתָּא וְשֵׁיצֵי משֶׁה יָת עִבִידָא:
@88 וַחֲפָא עֲנָנָא יָת מַשְׁכַּן זִמְנָא וִיקָרָא דַיְיָ אִתְמְלֵי יָת מַשְׁכְּנָא:
@89 וְלָא יָכִיל משֶׁה לְמֵיעַל לְמַשְׁכַּן זִמְנָא אֲרֵי שְׁרָא עֲלוֹהִי עֲנָנָא וִיקָרָא דַיְיָ אִתְמְלִי יָת מַשְׁכְּנָא:
@90 וּבְאִסְתַּלָקוּת עֲנָנָא מֵעִלָוֵי מַשְׁכְּנָא נָטְלִין בְּנֵי יִשְׂרָאֵל בְּכֹל מַטְלָנֵיהוֹן:
@91 וְאִם לָא יִסְתַּלַק עֲנָנָא וְלָא נָטְלִין עַד יוֹמָא דְאִסְתַּלָקוּתֵהּ:
@92 אֲרֵי עֲנָנָא יְקָרָא דַיְיָ עַל מַשְׁכְּנָא בִּימָמָא וְחֵיזוּ אֶשָׁתָא הֲוֵי בְלֵילְיָא בֵּהּ לְעֵינֵי כָל בֵּית יִשְׂרָאֵל בְּכָל מַטְלָנֵיהוֹן: חזק:

@1 **אלה פקודי.** בפרשה זו נמנו כל משקלי נדבת המשכן, לכסף ולזהב ולנחשת, ונמנו כל כליו לכל עבודתו: **המשכן משכן.** שני פעמים, רמז למקדש שנתמשכן בשני חורבנין על עונותיהן של ישראל: **משכן העדת.** עדות לישראל שותר להם הקדוש ברוך הוא על מעשה העגל, שהרי השרה שכינתו ביניהם: **עבדת הלוים.** פקודי המשכן וכליו היא עבודה המסורה ללוים במדבר, לשאת ולהוריד להקים איש איש למשאו המפקד עליו, כמו שאמרו בפרשת נשא (במדבר ד) : **ביד איתמר.** הוא היה פקיד עליהם למסור לכל בית אב עבודה שעליו:
@2 **ובצלאל בן אורי** וגו' **עשה את כל אשר צוה ה' את משה.** אשר צוה משה אין כתיב כאן, אלא כל אשר צוה ה' את משה, אפלו דברים שלא אמר לו רבו, הסכימה דעתו למה שנאמר למשה בסיני, כי משה צוה לבצלאל לעשות תחלה כלים ואחר כך משכן, אמר לו בצלאל מנהג עולם לעשות תחלה בית ואחר כך משים כלים בתוכו. אמר לו כך שמעתי מפי הקדוש ברוך הוא. אמר לו משה בצל אל היית, כי בודאי כך צוה לי הקדוש ברוך הוא, וכן עשה המשכן תחלה ואחר כך עשה הכלים:
@4 **ככר.** ששים מנה, ומנה של קדש כפול היה, הרי הככר מאה ועשרים מנה, והמנה עשרים וחמשה סלעים, הרי ככר של קדש שלשת אלפים שקלים, לפיכך מנה בפרוטרוט כל השקלים שפחותין במנינם משלשת אלפים שאין מגיעין לככר:
@6 **בקע.** הוא שם משקל של מחצית השקל: **לשש מאות אלף** וגו' **.** כך היו ישראל, וכך עלה מנינם אחר שהוקם המשכן בספר במדבר. ואף עתה בנדבת המשכן כך היו. ומנין חצאי השקלים של שש מאות אלף עולה מאת ככר, כל אחד של שלשת אלפים שקלים, כיצד, שש מאות אלף חצאין הרי הן שלש מאות אלף שלמים, הרי מאת ככר, והשלשת אלפים וחמש מאות וחמשים חצאין עולין אלף ושבע מאות וחמשה ושבעים שקלים:
@7 **לצקת.** כתרגומו לאתכא: **את אדני הקדש.** של קרשי המשכן, שהם ארבעים ושמנה קרשים ולהם תשעים וששה אדנים, ואדני פרכת ארבעה, הרי מאה וכל שאר האדנים נחשת כתיב בהם:
@8 **וצפה ראשיהם.** של עמודים, מהן, שבכלן כתיב וצפה ראשיהם וחשוקיהם כסף.
@12 **ומן התכלת והארגמן** וגו' **.** שש לא נאמר כאן, ומכאן אני אומר, שאין בגדי שרד הללו בגדי כהנה, שבבגדי כהנה היה שש, אלא הם בגדים שמכסים בהם כלי הקדש בשעת סלוק מסעות, שלא היה בהם שש:
@14 **וירקעו.** כמו (תהלים קלו ו) לרוקע הארץ, כתרגומו ורדידו טסין היו מרדדין מן הזהב, אישטינדר''א בלעז , טסין דקין. כאן הוא מלמדך, היאך היו טווין את הזהב עם החוטין מרדדין הטסין דקין וקוצצין מהן פתילים לאורך הטס, לעשות אותן פתילים מעורבין עם כל מין ומין בחשן ואפוד שנאמר בהן זהב, חוט אחד של זהב עם ששה חוטין של תכלת, וכן עם כל מין ומין. שכל המינים חוטן כפול ששה, והזהב חוט שביעי עם כל אחד ואחד:
@39 **ואת פארי המגבעות.** תפארת המגבעות, המגבעות המפוארות:
@42 **לתת על המצנפת מלמעלה.** ועל ידי הפתילים היה מושיבו על המצנפת כמין כתר, ואי אפשר לומר הציץ על מצנפת שהרי בשחיטת קדשים שנינו (זבחים יט א) שערו היה נראה בין ציץ למצנפת, ששם מניח תפלין, והציץ היה נתון על המצח, הרי המצנפת למעלה והציץ למטה, ומהו על המצנפת מלמעלה, ועוד הקשיתי בה, כאן הוא אומר ויתנו עליו פתיל תכלת, ובענין הצואה הוא אומר (שמות כח לז) ושמת אותו על פתיל תכלת. ואומר אני פתיל תכלת זה חוטין הן לקשרו בהן במצנפת, לפי שהציץ אינו אלא מאוזן לאוזן, ובמה יקשרנו במצחו, והיו קבועין בו חוטי תכלת לשני ראשיו ובאמצעיתו, שבהן קושרו ותולהו במצנפת כשהוא בראשו, ושני חוטין היו בכל קצה וקצה אחד ממעל ואחד מתחת לצד מצחו, וכן באמצעו, שכך הוא נוח לקשור, ואין דרך קשירה בפחות משני חוטין, לכך נאמר (שמות כח לז) על פתיל תכלת, ועליו פתיל תכלת, וקשר ראשיהם השנים כלם יחד מאחוריו למול ערפו, ומושיבו על המצנפת. ואל תתמה שלא נאמר פתילי תכלת, הואיל ומרבין הן, שהרי מצינו בחשן ואפוד וירכסו את החשן וגו' בפתיל תכלת. ועל כרחך פחות משנים לא היו, שהרי בשתי קצות החשן היו שתי טבעות החשן, ובשתי כתפות האפוד היו שתי טבעות האפוד שכנגדן, ולפי דרך קשירה ארבע חוטין היו, ומכל מקום פחות משנים אי אפשר:
@43 **ויעשו בני ישראל.** את המלאכה ככל אשר צוה ה' וגו' :
@44 **ויביאו את המשכן** וגו' **.** שלא היו יכולין להקימו, ולפי שלא עשה משה שום מלאכה במשכן, הניח לו הקדוש ברוך הוא הקמתו, שלא היה יכול להקימו שום אדם מחמת כובד הקרשים, שאין כח באדם לזקפן, ומשה העמידו. אמר משה לפני הקדוש ברוך הוא איך אפשר הקמתו על ידי אדם, אמר לו עסוק אתה בידך נראה כמקימו, והוא נזקף וקם מאליו, וזהו שנאמר (שמות מ יז) הוקם המשכן, הוקם מאליו. מדרש רבי תנחומא:
@54 **ויברך אתם משה.** אמר להם יהי רצון שתשרה שכינה במעשה ידיכם, (תהלים צ יז) ויהי נעם ה' אלהינו עלינו ומעשה ידינו וגו' , והוא אחד מאחד עשר מזמורים שבתפלה למשה:
@57 **וסכת על הארן.** לשון הגנה, שהרי מחצה היתה:
@58 **וערכת את ערכו.** שתי מערכות של לחם הפנים:
@73 **ויפרש את האהל.** הן יריעות העזים:
@74 **את העדות.** הלוחות:
@76 **על ירך המשכן צפונה.** בחצי הצפוני של רוחב הבית: **ירך.** כתרגומו צדא, כירך הזה שהוא בצדו של אדם:
@81 **ויקטר עליו.** אהרן: **קטרת.** שחרית וערבית, כמו שנאמר (שמות ל ז) בבקר בבקר בהיטיבו את הנרות וגו' :
@83 **ויעל עליו** וגו' **.** אף ביום השמיני למלואים, שהוא יום הקמת המשכן, שמש משה והקריב קרבנות צבור, חוץ מאותן שנצטוו בו ביום, שנאמר (ויקרא ט ז) קרב אל המזבח וגו' : **את העלה.** עולת התמיד: **ואת המנחה.** מנחת נסכים של תמיד, כמו שנאמר (שמות כט מ) ועשרן סלת בלול בשמן וגו' :
@85 **ורחצו ממנו משה ואהרן ובניו.** יום שמיני למלואים הושוו כלם לכהנה, ותרגומו ומקדשין מניה, בו ביום קדש משה עמהם:
@86 **ובקרבתם.** כמו ובקרבם כשיקרבו:
@89 **ולא יכל משה לבוא אל אהל מועד.** וכתוב אחד אומר (במדבר ז פט) ובבא משה אל אהל מועד, בא הכתוב השלישי והכריע ביניהם, כי שכן עליו הענן, אמור מעתה כל זמן שהיה עליו הענן לא היה יכול לבא, נסתלק הענן נכנס ומדבר עמו:
@92 **לעיני כל בית ישראל בכל מסעיהם.** בכל מסע שהיו נוסעים היה הענן שוכן במקום אשר יחנו שם. מקום חניתן אף הוא קרוי מסע, וכן (בראשית יג ג) וילך למסעיו, וכן (במדבר לג א) אלה מסעי לפי שממקום החניה חזרו ונסעו, לכך נקראו כלן מסעות:

@1 אמר **המשכן משכן העדות** . בעבור כי יריעות שש משזר הם שיקראו משכן במצוה (לעיל כו א) ובמעשה (לעיל לו ח), אבל משכן העדות כולל הבית בכללו שהוא המשכן הנעשה ללוחות העדות:
@1 **ועל דעת רבים** (רש''י וראב''ע) **אלה פקודי המשכן** יחזור אל הנזכרים למעלה, יאמר כי המשכן וכליו שהוא הבית והחצר וכל הנעשה להם פקודי עבודת הלוים שפקדם משה ביד איתמר, ואין כלי הקדש הארון והשולחן והמנורה והמזבחות בכלל המשכן, כי הם ביד אלעזר. ואין כן דעתי, כי למה יזכיר פקודת איתמר ולא יזכיר פקודת אלעזר שהיא הנכבדת. אבל אלה פקודי ירמוז אשר יזכיר בפרשה למטה, יאמר כי כסף פקודי העדה מאת ככר שנעשה בו האדנים והווים לעמודים וצפוייהם וחשוקיהם (פסוקים כה~כח), ונחשת התנופה שהוא שבעים ככר שעשה בה מזבח הנחשת והמכבר וכל כליו ואדני החצרות והיתדות (פסוקים כט~לא), הכל נתן משה במספר במשקל ביד איתמר:
@1 **ולא** ספר בפרשה מה נעשה בזהב, כי הזהב ממנו ביד איתמר ציפוי הקרשים והבריחים, וממנו ביד אלעזר הארון והכפורת והמנורה והשולחן ומזבח הזהב. והנה בעבור שלא יודע צפוי כל כלי כמה זהב יש בו לא ספר שנתנו משה להם במנין ובמשקל. ולכך לא הזכיר כאן פקודת אלעזר, כי לא בא הכתוב עתה רק לדבר על מלאכת המשכן לא על המסעות. ואל יקשה עליך בעבור שימנה כאן מזבח הנחשת והוא פקודת אלעזר, כי יצטרך לומר שעשאוהו מנחשת התנופה, ולא יחוש להוציא דבר אחד מכלל הדברים שאמר בהן שהם ביד איתמר, כי כן דרך הכתוב במקומות הרבה (בראשית לה כו שם מו כז):
@1 **ולא** הזכיר בכאן הכיור וכנו, כי לא נעשה במשקל, אבל כל המראות שהביאו הנשים הצובאות שם בהם ולא ידע משה משקלו. ויתכן שלא היה בפקודת איתמר, כי יכנס בכלל מה שאמר הכתוב (במדבר ג לא) ומשמרתם הארון והשלחן והמנורה והמזבחות וכלי הקדש אשר ישרתו בהם, כי בכיור וכנו ישרתו למזבח, והנה איננו בחשבון הפרשה הזו:
@2 **ובצלאל בן אורי בן חור למטה יהודה עשה את כל אשר צוה ה'** . הענין כי על פיו נעשה הכל, כי הוא המורה לכל החכמים, ולפניו היו עושים כולם ומראים אליו כל מלאכתם, כמו שאמר (לעיל לה לד) ולהורות נתן בלבו, אבל גם כל חכמי לב עשו במלאכה, כמו שאמר (שם לו ח) ויעשו כל חכם לב בעושי המלאכה את המשכן. ועל דעת רבותינו (ירושלמי פאה א א) יהיה זה לשבח אותו ולומר שאפילו דברים שלא אמר לו רבו הסכימה דעתו למה שנאמר למשה מסיני, ולא בא הכתוב לומר שהוא עשה הכל, אלא שקיים בכל הנעשה על ידו כל אשר צוה ה' את משה, ולפיכך לא אמר בכל הנעשה עד הנה כאשר דבר ה' אל משה, כי היה במשמע כאשר אמר משה בדבר ה', והוא שנה הסדר בהם ממה שאמר לו משה, ולפיכך כלל זה בכאן לומר שעשה הכל כאשר אמר השם, כמו שכתבתי למעלה (לו ח):
@7 **את אדני הקדש ואת אדני הפרכת** . יקרא הכתוב המשכן קדש, והבדיל הפרכת, בעבור היותו מבדיל בין הקדש ובין קדש הקדשים, כאלו אמר את אדני הקדש ואת אדני קדש הקדשים:
@14 **וירקעו את פחי הזהב** . לא הוסיף בכל מלאכת הקדש לפרש דרך האומנות איך נעשה, זולתי בכאן, והראוי שיאמר ויעשו את האפוד זהב תכלת וגו' מעשה חושב, כתפות עשו לו וגו', כי כן הדרך בכולם. ויתכן שספר בכאן המחשבה שחדשו בחוטי הזהב, כי היה תמה בעיניהם להיות זהב טווי ושזור כאשר יעשו בצמר ופשתים, כי לא נשמע עד היום ההוא לעשות כן:
@35 (כד כה) וטעם **ויעשו על שולי המעיל רמוני תכלת וארגמן** . שעשו הרמונים לתת אותם על שולי המעיל סביב, ועשו פעמוני זהב טהור, וישימו הפעמונים בתוך הרמונים קודם שיתנו אותם במעיל, והנה הפעמונים בתוך הרמונים בתלוש, וישימו **הרמונים על שולי המעיל סביב** והפעמונים בתוכם. ולכך כפל הכתוב בתוך הרמונים פעמים, כי היו בתוכם מתחלה ובשעה שתלו אותם על שולי המעיל סביב. וגם זו ראיה למה שפירשנו בסדר ואתה תצוה (לעיל כח לא):
@38 (כז~כח) **ויעשו את הכתנת שש מעשה אורג לאהרן ולבניו** . נראה מכאן שהיו הכתנות שוות באב ובבנים אע''פ שאמר באהרן ושבצת הכתנת שש (לעיל כח לט) ובבניו אמר סתם תעשה כתנות (שם מ), כי הכוונה תעשה כתנות כמו הנזכרת, וכן כתוב (שם ד) חושן ואפוד ומעיל וכתנת תשבץ מצנפת ואבנט ועשו בגדי קדש לאהרן אחיך ולבניו לכהנו לי, כי לאהרן ולבניו יחזרו אל כתונת תשבץ מצנפת ואבנט כי הם שוים בכולם. וכן מה שאמר כאן (בפסוק הבא) ואת המצנפת שש ואת פארי המגבעות כלל אהרן ובניו, כי המצנפת והמגבעות אחד הם במעשה, אלא שאהרן יצנף אותה ובניו יחבשו בהן ראשם כאשר פירשתי (לעיל כח לא, לז):
@38 **ולשון פארי המגבעות** , שהיו עולות על הראש כפארים, מלשון הפארים והצעדות (ישעיה ג כ), פארי פשתים יהיו על ראשם (יחזקאל מד יח):
@40 ופירש באבנט שעשו אותו **שש משזר ותכלת וארגמן ותולעת שני** . ולא נתפרש זה בצואה רק מה שנאמר באבנט תעשה מעשה רוקם (לעיל כח לט) נודע שהוא רקום בארבע מינין הללו כמו שנאמר במסך (לעיל כו לו) ועשית מסך לפתח האהל תכלת וארגמן ותולעת שני מעשה רוקם:
@40 **והאבנט** הזה הוא גם באהרן ובניו כדעת האומר (יומא יב.) אבנטו של כהן גדול זהו אבנטו של כהן הדיוט. ועל דעת האומר (שם) לא זהו אבנטו של כהן הדיוט פירש בשל אהרן שהוא מעשה רוקם ולא הוצרך להזכיר של בניו שהוא שש, כמו שאמר (לעיל כח מ) ולבני אהרן תעשה כתנות ועשית להם אבנטים ומגבעות תעשה להם, וכולן שש ככתנת:
@44 **ויביאו את המשכן אל משה את האהל ואת כל כליו** . שיעור הכתוב בזה כמו בוא''ו, **ויביאו את המשכן אל משה ואת האהל ואת כל כליו** , כי יריעות שש משזר הן ששמן משכן, כמו שאמר (לעיל כו א) ואת המשכן תעשה עשר יריעות שש משזר, ואמר בהן (שם ו) וחברת את היריעות והיה המשכן אחד, ויריעות העזים הן האהל, כאשר יאמר בהן ועשית יריעות עזים לאהל על המשכן (שם ז), וחברת את האהל והיה אחד (שם יא). וכן את המשכן את אהלו ואת מכסהו (לעיל לה יא) ואת אהלו. אף כאן, ויביאו את המשכן אל משה ואת האהל ואת כל כליו, כי יזכיר שמות הכל. ולפעמים יקרא כל הבית אהל מועד, כאשר אמר (לעיל לא ו ז) ועשו את כל אשר צויתיך את אהל מועד ואת הארון לעדות, כי אהל מועד הוא הבית בכללו אשר יועד אליו שמה, וכן כל כלי עבודת המשכן לאהל מועד (להלן פסוק מ):
@48 **את נרותיה נרות המערכה** . יתכן שדרך המנורות להיות בהן נרות לנוי או להרבות בהן אור לפרקים, ואין כן במנורת הקדש כי לא היו בה רק שבעת הנרות, ועל כן פירש נרות המערכה, כי הן אשר יערוך אותן בין הערבים:
@53 וטעם **כן עשו בני ישראל את כל העבודה** . כל מלאכת המשכן, ויקראנה עבודה לומר כי עשו אותה לעבודת השם הנכבד, כענין ועבדתם את ה' אלהיכם (לעיל כג כה), ואותו תעבודו (דברים יג ה). ויתכן שיאמר בכאן כל העבודה על הכלים, כלשון שאמר (לעיל פסוק מ) את כל כלי עבודת המשכן, והזכיר תחלה הכלים לאמר כי אפילו בכלים נזהרו ועשו כמצוה בהם, ואחרי כן הזכיר וירא משה את כל המלאכה:
@56 **ביום החדש הראשון באחד לחדש תקים את משכן אהל מועד** . על דעת רבותינו (בתורת כהנים סוף פרשת צו סימן קצא, ועוד) שהוא יום שמיני למלואים טעם הכתוב שתקים את המשכן ויעמד כן ולא תורידנו ולא תקימו עוד, כי בנסוע המחנות הלוים יורידו אותו ויקימו אותו. ולא הוצרך לצוות עתה על הקמת שבעת הימים הראשונים, כי אמר לו מתחלה והקמות את המשכן כמשפטו אשר הראית בהר (לעיל כו ל), וכיון שפירש לו עתה כי ביום החדש הראשון תהיה הקמתו לעמדה, הנה ידע כי שבעת ימי המלואים יצטרך להקים ולהוריד. ואולי היה כן להרגיל הלוים במעשהו כי ממנו יראו וכן יעשו, או היה להכתיר היום בעטרה זו:
@56 **ונראה** לדעתם כי בשבעת הימים הראשונים היה מקים אותו בבקר בבקר, ועומד כן כל היום וכל הלילה, וכעלות השחר היה מוריד אותו וחוזר ומקימו מיד, כי הכתוב אמר ופתח אהל מועד תשבו יומם ולילה (ויקרא ח לה), ואין פתח לאהל רק בעת הקמתו:
@56 **וכבר** דרשו (בתורת כהנים ויקרא א ה) אל פתח אהל מועד, בזמן שהוא פתוח ולא בזמן שהוא מפורק. ואמרו (זבחים נה:) שלמים ששחטן קודם שנפתחו דלתות ההיכל פסולין, שנאמר (ויקרא ג ב) ושחטו פתח אהל מועד, בזמן שפתוח ולא בזמן שנעול, וכן במשכן, עד שלא העמידו הלוים את המשכן ואחר שפרקו הלוים את המשכן פסולין. ועוד, שהיה מקריב בו תמיד של בין הערבים ומדליק את הנרות בערב:
@56 **ובויקרא** רבה (עי' במדבר רבה יב טו) ראיתי, היה משה מעמידו ומפרקו שני פעמים בכל יום, רבי חנינא הגדול אומר שלשה פעמים בכל יום, שנאמר תקים (פסוק ב) הוקם (פסוק יז) ויקם (פסוק יח), אחת לתמיד של שחר, ואחת למלואים, ואחת לתמיד של בין הערבים. ויתכן שכל זה רגילות, להודיע ענין הקמתו והסדר, ולא יעמידנו מפורק כלל:
@56 **והכתוב** שאמר כאן ויכס הענן את אהל מועד וכבוד ה' מלא את המשכן (להלן פסוק לד) על דעתם היה זה ביום השמיני, כי אמר ויכל משה את המלאכה (שם פסוק לג), וכאשר כלה הקמה זו של אחד בניסן כסה הענן את המשכן. וכבר כתב רש''י (ויקרא ט כג) מה שדרשו (בתורת כהנים שם) ויצאו ויברכו את העם, לפי שכל שבעת ימי המלואים שהעמיד משה המשכן והיה משמש בו ומפרקו לא שרתה בו שכינה והיו ישראל נכלמים ואמרו למשה, משה רבינו כל הטורח שטרחנו שתשרה שכינה בינינו ונדע שנתכפר לנו עון העגל, אמר להם אהרן אחי כדאי וחשוב ממני שעל ידי קרבנותיו ועבודתו תשרה בנו שכינה:
@56 **ובפרשת** מלואים (תורת כהנים שם) יכול הוקם המשכן בראש חדש ושרתה שכינה בשמיני בחדש, תלמוד לומר וביום הקים את המשכן כסה הענן את המשכן לאהל העדות (במדבר ט טו), מלמד שביום שהוקם המשכן שרתה השכינה על ידי מעשה אהרן. הנה יאמרו בפירוש כי כסוי הענן את המשכן בשמיני למלואים היה, והוא אחד בניסן, אם כן תהיה כל הפרשה הזאת לדעתם ביום השמיני. והיה זה מפני שהכתוב יסדר כי צוה השם את משה שתהיה הקמת המשכן לכלותה ביום החדש הראשון באחד לחדש, ואמר כי משה עשה כן וכלה את כל המלאכה ואז כסה הענן את האהל, וכן תמיד. וחזר הכתוב אל תחלת הדבור אשר היה למשה מן האהל ואמר ויקרא אל משה (ויקרא א א), וכל זה בסדר נכון:
@56 **וכדמות** ראיה להם מה שכתוב (במדבר ז א) ויהי ביום כלות משה להקים את המשכן, ואם לא הוריד אותו מה טעם ביום כלות, כי ביום אחד החל וכלה, והראוי שיאמר ויהי ביום הקים משה את המשכן. ועוד, שאמר שם זה הדבר אשר צוה ה' תעשו (ויקרא ט ו), וירא כבוד ה' אל כל העם (שם כג), ומשמעות זה שעדיין לא כסה הענן את אהל מועד ולא מלא כבוד ה' את המשכן. ומ''מ ביום ראשון של מלואים נדבר למשה משם כל הפרשיות הנאמרות מתחלת ספר ויקרא עד ויהי ביום השמיני (שם ט א), אבל לא היה הענן מכסה אותו, והיו סבורין שהיה הדבור למשה שם מן השמים כאשר היה בארץ מצרים:
@56 **אבל** במדרש חזית (קהלת א יב) מצאתי, ויהי ביום השמיני, זה היה ראוי להיות תחלת הספר, ולמה נכתב כאן, אלא שאין מוקדם ומאוחר בתורה, ואם כן יהיה ויקרא אל משה מאהל מועד אחר וירא כבוד ה' אל כל העם ותצא אש ותאכל על המזבח (ויקרא ט כג כד), ויהיה הדבור לאהרן יין ושכר אל תשת (שם י ט) ממחרת, כי לא יתכן שנדבר לאהרן מאהל מועד קודם למשה. ואיני יודע אם זה דברי הכל או הם דברי יחיד, כי על דברי ר' ישמעאל נאמרו שם:
@56 **תקים את משכן אהל מועד** . לא פירש לו בצואה זו כיצד סדר ההקמה כאשר פירש במעשה ויתן את אדניו וישם את קרשיו (פסוק יח). והיה זה, מפני שכבר הראה אותו ההקמה במראית העין, כמו שאמר והקמות את המשכן כמשפטו אשר הראית בהר (לעיל כו ל). וכן קצר כאן ואמר ושמת שם את ארון העדות (בפסוק הבא), ולא הזכיר ואל הארון תתן את העדות, כי בהזכירו ''את ארון העדות'' יבין זה, כי לא יקרא הארון כן רק בהיות בו לוחות העדות. וכבר נצטוה מתחלה ונתת את הכפרת על הארון מלמעלה ואל הארון תתן את העדות אשר אתן אליך (לעיל כה כא), ולא הוצרך כאן אלא לצוותו בהקדמה, כי תשומת הארון עם הלוחות יקדים לכל הכלים. וכן קצר בענין השולחן והמנורה, שכבר צוה אותו (לעיל כו לה) באיזה מקום מן המשכן יעמידם. וקצר בענין לבישת אהרן ובניו, שאמר והלבשת את אהרן את בגדי הקדש (להלן פסוק יג), ובבניו אמר והלבשתם כתנות (להלן פסוק יד), כי כבר צוה אותו בפרט בסדר לבישתן (לעיל כט ה~ט), ולא בא עכשיו אלא לסדר לו שעת הלבישה שתהיה אחר הקמת המשכן כלו. והזכיר כתנות שבהן יתחיל הלבישה:
@57 וטעם **וסכות על הארון** . מלמעלה במקום אל, כי וסכות מלשון מסך. וכן וישם את פרוכת המסך ויסך על ארון העדות (להלן פסוק כא):
@64 **והיה המזבח קדש קדשים** . בעבור שיקריבו בו גם קדשי הקדשים אמר בו כן אף על פי שהיה בחצר. ואמר גם במשכן (בפסוק הקודם) והיה קדש, כי לא נקרא קדש קדשים רק מקום משכן הארון, כמו שנאמר (לעיל כו לג) והבדילה הפרכת לכם בין הקדש ובין קדש הקדשים. ויתכן שאמר במזבח קדש קדשים בעבור שיקדש, כמו שאמר והיה המזבח קדש קדשים כל הנוגע במזבח יקדש (לעיל כט לז):
@71 **ויהי בחדש הראשון באחד לחודש** . על דעת רבותינו הזכיר הכתוב שהוקם המשכן לעמוד כן באחד לחודש הראשון כאשר צוה (לעיל פסוק ב). ואמרו ויקם משה את המשכן (פסוק יח), לספר מה שעשה בהקימו אותו מן היום הראשון שהתחיל בו שהוא כ''ג באדר. ולא הזכיר בכאן משיחת המשכן וכליו ולא משיחת אהרן ובניו וקרבנות המלואים, כי לא עשה אותם עד שסיים כל ההקמה ונצטוה בהם פעם שנית קח את אהרן, כמו שמפורש בפרשת צו (ויקרא ח ב):
@71 **והנה** המשכן וכליו לא נתקדשו לעבודה אלא במשיחה, כמו שנאמר (לעיל פסוק ט) ומשחת את המשכן ואת כל אשר בו וקדשת אותו ואת כל כליו, על כן פירוש ויערוך עליו ערך לחם (פסוק כג), ויעל הנרות (פסוק כה), כי עשה כן בזמנם אחר המשיחה. והנה הם כטעם לעשות כן. ומה שאמר גם כן למעלה (פסוק ד) והבאת את השולחן וערכת את ערכו, יצוה שיערוך אותו אחרי המשיחה. וכן אמר ונתת את מזבח הזהב לקטורת (פסוק ה), וכן ויעל עליו את העולה ואת המנחה (להלן פסוק כט), בזמנה, כי עדיין לא הקים החצר סביב למשכן, ואין מקריבין בלא קלעים, כי יהיו שחוטי חוץ, אלא כלם בזמנם:
@74 וטעם **ויקח ויתן את העדות** (שם פסוק כ). שלקח הלוחות מארון עץ שהיו שם בתוך אהל משה והביא אותם אל המשכן:
@81 **ויקטר עליו קטורת סמים** . משה הקטיר עליו כל שבעת ימי המלואים. ואע''פ שלא אמר בצואה (בפסוק ה) והקטיר עליו קטורת סמים, הבין זה משאר העבודות כלן, שהרי צוה אותו בכאן (בפסוק ד) שיסדר הלחם ויעלה הנרות. וכן ויעל עליו את העולה ואת המנחה (להלן פסוק כט), משה הוא המעלה, שכן נצטוה (לעיל כט לח) וזה אשר תעשה על המזבח, שיתחיל הוא לעשות כן בעבדו בימי המלואים, כי הצואות כולן שם (מפסוק א ואילך) על עבודת משה. ואמר אחרי כן (בפסוק מב) עולת תמיד לדורותיכם, שיעשו כן הכהנים לדורות. ולכך אמר בה בסדר פנחס (במדבר כח ו) עולת תמיד העשויה בהר סיני, שהתחיל אותה משה שם:
@81 **והנה** משה רבינו בכל העבודות הכהן הראשון, ולפיכך הקטיר גם הקטרת. ואולי בכלל ונתת את מזבח הזהב לקטרת (פסוק ה) שתקטירנו עליו מיד. ומה שאמר בצואה (לעיל ל ו ז) ונתת אותו לפני הפרוכת והקטיר עליו אהרן קטורת סמים, להורות על ענינו מיום שהתחיל אהרן בכהונתו ולעולם, שכך אמר (שם ל ח) ובהעלות אהרן את הנרות בין הערבים, ואין הדבר אלא מיום זה ואילך, כי בכאן (בפסוק ד) צוה למשה בפירוש והעלית את נרותיה. ובפירוש רש''י (בפסוק שלפנינו) ראיתי, ויקטר עליו אהרן קטורת שחרית וערבית, כמה שנאמר (לעיל ל ז ח) בבקר בבקר בהטיבו את הנרות וגו', ובהעלות אהרן את הנרות בין הערבים וגו'. ולא ידעתי אם הוא טעות סופרים:
@88 **ויכס הענן את אהל מועד** . אמר כי הענן יכסה את האהל מכל צד והוא מכוסה וטמון בו. **וכבוד ה' מלא את המשכן** , כי תוכו מלא הכבוד, כי הכבוד שוכן בתוך הענן תוך המשכן, כענין שנאמר בהר סיני (לעיל כ כא) אל הערפל אשר שם האלהים. ואמר כי לא יכול משה לבא אל אהל מועד (פסוק הבא) אפילו אל הפתח, מפני שהיה הענן מכסה אותו ולא היה רשאי לבא בתוך הענן. ועוד, כי המשכן מלא כבוד ה' ואיך יכנס בו. והטעם, שלא יבא שם בלא רשות, אבל יקרא אותו ויבא בתוך הענן כאשר עשה בהר סיני ויקרא אל משה ביום השביעי מתוך הענן (לעיל כד טז), ואמר ויבא משה בתוך הענן (שם יח). ועל דרך הפשט, בעבור שנאמר וידבר ה' אליו מאהל מועד (ויקרא א א) לא נכנס משה למשכן, אבל קרא אותו מאהל מועד ועמד פתח אהל מועד וידבר אליו:
@88 **ורבותינו** אמרו (ת''כ פתיחתא ח) כתוב אחד אומר **ולא יכול משה לבא אל אהל מועד** , וכתוב אחר אומר **ובבוא משה אל אהל מועד** (במדבר ז פט), הכריע **כי שכן עליו הענן** . כי לדעתם **ובבא משה אל אהל מועד** , שיבא שם בלא קריאה מדעתו, או מפני שאמר שם וישמע את הקול מדבר אליו מעל הכפורת נראה להם שהיה משה עומד בתוך האהל לפני הכפרת, וכל עת היות כבוד השם מלא את המשכן לא נכנס משה בתוכו. ולכך יאמרו שהיה זה לאחר שנסתלק הענן, כלומר שנסתלק מלכסות כל האהל ואין הכבוד מלא את המשכן, כי לא היה זה רק ביום השמיני ברדת שם הכבוד. והקריאה שאמר ויקרא אל משה וידבר ה' אליו מאהל מועד (ויקרא א א), על דעתם קודם לכן היתה, כאשר פירשתי למעלה (בפסוק ב). ויתכן שהכתוב שיאמר פעם אחרת **וכבוד ה' מלא את המשכן** ירמוז אל הכבוד השוכן בקרבו:
@88 והנה נשלם ספר הגאולה אשר ה' אלהי ישראל בא בולבני ישראל עם קרובו, הושיעו מיד שונאו וגאלו מיד אויבוואליו יבא באלפי שנאן ודכב רבוא, לתת לו תורת אמת להנחיל יש את אוהבובנה בית זבול לשכון שכינתו על כרובו, ומקדש למקדש שהמלך במסבו.וברוך ה' החפץ שלום עבדו, אשר עד הנה עזרו לבאהמחדש נעוריו בשיבו, המשביע בתודתו רעבווינקהו דבש וחלבו, כי הכין כל לבבוולשמו יברך בקרו וערבו, ברוך שאכלנו משלו וחיינו בטובו.ברוך דיהב חילא לעבדיה בר אמתיה, ברוך הנותן ליעף כח ולאין אונים עצמה ירבה:
